#include <stdio.h>
#include <stdbool.h>
#include <string.h>
#include <stdlib.h>

#include <threads.h>
#include <stddef.h>
#define QCAP 4
typedef struct {
    long items[QCAP];
    size_t head, count;
    mtx_t m;
    cnd_t not_full, not_empty;
} BQ;
/* ---- reference queue (correct; defined here) ---- */
static void bq_ref_init(BQ *q) {
    q->head = 0; q->count = 0;
    mtx_init(&q->m, mtx_plain);
    cnd_init(&q->not_full);
    cnd_init(&q->not_empty);
}
static void bq_ref_destroy(BQ *q) {
    mtx_destroy(&q->m);
    cnd_destroy(&q->not_full);
    cnd_destroy(&q->not_empty);
}
static int bq_ref_push(BQ *q, long v) {
    if (!q) return -1;
    mtx_lock(&q->m);
    while (q->count == QCAP)
        cnd_wait(&q->not_full, &q->m);
    q->items[(q->head + q->count) % QCAP] = v;
    q->count++;
    cnd_signal(&q->not_empty);
    mtx_unlock(&q->m);
    return 0;
}
static int bq_ref_pop(BQ *q, long *out) {
    if (!q || !out) return -1;
    mtx_lock(&q->m);
    while (q->count == 0)
        cnd_wait(&q->not_empty, &q->m);
    *out = q->items[q->head];
    q->head = (q->head + 1) % QCAP;
    q->count--;
    cnd_signal(&q->not_full);
    mtx_unlock(&q->m);
    return 0;
}
/* ---- completion latch (shared, non-static) ---- */
int producers_done = 0;
mtx_t done_m;
cnd_t done_cv;
static void pipeline_reset(void) {
    static int inited = 0;
    if (!inited) { mtx_init(&done_m, mtx_plain); cnd_init(&done_cv); inited = 1; }
    producers_done = 0;
}
/* ---- YOUR worker bodies ---- */
int producer_body(BQ *q, int n);
int consumer_body(BQ *q, int expected, long *sum);
/* ---- harness (reference; defined here) ---- */
typedef struct { BQ *q; int n; } PArgs;
typedef struct { BQ *q; int expected; long *sum; } CArgs;
static int producer_entry(void *p) { PArgs *a = p; return producer_body(a->q, a->n); }
static int consumer_entry(void *p) { CArgs *a = p; return consumer_body(a->q, a->expected, a->sum); }
static int run_pipeline(BQ *q, int n, long *total) {
    if (!q || !total || n < 0) return -1;
    pipeline_reset();
    PArgs pa = { q, n };
    CArgs ca = { q, n, total };
    thrd_t pt, ct;
    if (thrd_create(&ct, consumer_entry, &ca) != thrd_success) return -1;
    if (thrd_create(&pt, producer_entry, &pa) != thrd_success) return -1;
    thrd_join(pt, NULL);
    thrd_join(ct, NULL);
    return 0;
}

